  '.gitattributes',
  '.gitignore',
  '.gitmodules',
  'CODE_OF_CONDUCT.md',
  'CONTRIBUTING.md',
  'LICENSE',
  'README.md',
  'SECURITY.md',
  'decisions',
  'docs',
  'governance',
  'profiles',
  'registry',
  'scripts',
