        '并在 docs/directory-guide.md 里登记（见 docs/directory-guide.md §4）。',
    );
  } else {
    ok(`${tracked.size} 个顶层跟踪条目全部在白名单内`);
  }

  const localOnly = readdirSync(ROOT, { withFileTypes: true })
    .map((e) => e.name)
    .filter((n) => n !== '.git' && !tracked.has(n));
